from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    result = []  # Initialize an empty list to store the separated groups
    start = 0
    count = 0

    for i, char in enumerate(paren_string):
        if char == '(':
            count += 1
            if count == 1:
                start = i
        elif char == ')':
            count -= 1
            if count == 0:
                result.append(paren_string[start:i+1])  # Separate each group into individual strings and add them to the list

    return result  # Return the list of separated groups

